#!/usr/bin/env python3
"""Generate the deterministic PDF fixtures used by the PDF import tests.

Run from the repository root:

    python3 tests/fixtures/pdf_import/generate.py

Everything except ``pdf_encrypted.pdf`` is produced with the standard library
only, via :mod:`pdf_builder`.  ``pdf_encrypted.pdf`` needs the external
``qpdf`` binary; when ``qpdf`` is missing the script skips it, keeps the
previously committed copy untouched, and exits with a warning.

The generated bytes are committed to the repository so the test-suite never
depends on ``qpdf`` or on regeneration to run.
"""

from __future__ import annotations

import os
import shutil
import subprocess
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import pdf_builder  # noqa: E402  (import needs the path fix above)

