MANY_PAGES_TITLE = "Documento de prueba para el límite de páginas"


def _multipage_blocks() -> list:
    """Three sheets, one logical CV spread over them."""
    blocks = []
    for number in (1, 2, 3):
        for line in MULTIPAGE:
            blocks.append(line.replace("%d", str(number)))
    return blocks


def _many_pages_blocks(pages: int = 21) -> list:
    blocks = [MANY_PAGES_TITLE, ""]
    for number in range(1, pages + 1):
        blocks.append("Página %d de %d" % (number, pages))
        blocks.append("Contenido de relleno determinista para la página %d." % number)
        blocks.append("")
    return blocks


def _write(path: str, payload: bytes) -> None:
    with open(path, "wb") as handle:
        handle.write(payload)


def _generate_encrypted() -> str:
    """Build ``pdf_encrypted.pdf`` with qpdf. Returns a status line."""
    qpdf = shutil.which("qpdf")
    if qpdf is None:
        return "SKIPPED: qpdf not available, keeping committed pdf_encrypted.pdf"

    source = pdf_builder.build_text_pdf(VALID_ES[:12], pages=1)
    with tempfile.TemporaryDirectory() as tmp:
        plain = os.path.join(tmp, "plain.pdf")
        with open(plain, "wb") as handle:
            handle.write(source)
        command = [
            qpdf,
            "--encrypt",
            ENCRYPTED_USER_PASSWORD,
            ENCRYPTED_OWNER_PASSWORD,
            "256",
            "--",
            plain,
            ENCRYPTED_PATH,
        ]
        completed = subprocess.run(command, capture_output=True, text=True)
    if completed.returncode != 0:
        return "FAILED: qpdf exited %d: %s" % (completed.returncode, completed.stderr.strip())
    return "OK: qpdf %s" % qpdf


def main() -> int:
    os.makedirs(PDF_DIR, exist_ok=True)

    written = []

    written.append(("valid_es.pdf", pdf_builder.build_text_pdf(VALID_ES, pages=1)))
    written.append(("valid_en.pdf", pdf_builder.build_text_pdf(VALID_EN, pages=1)))
    written.append(("ambiguous.pdf", pdf_builder.build_text_pdf(AMBIGUOUS, pages=1)))
    written.append(("multipage.pdf", pdf_builder.build_text_pdf(_multipage_blocks(), pages=3)))
    written.append(("empty_text.pdf", pdf_builder.build_empty_pdf(pages=1)))
    written.append(("corrupt.pdf", pdf_builder.build_corrupt_pdf(["CV corrupto", "segunda linea"])))
    written.append(("many_pages.pdf", pdf_builder.build_text_pdf(_many_pages_blocks(21), pages=21)))
    written.append(
        (
            "not_a_pdf.pdf",
            b"This file has a .pdf extension but its bytes are plain text.\n"
            b"It starts with 'Hola' instead of the %PDF- header.\n",
        )
    )

    for name, payload in written:
        path = os.path.join(PDF_DIR, name)
        _write(path, payload)
        print("wrote %-16s %6d bytes" % (name, len(payload)))

    print("wrote %-16s %s" % ("pdf_encrypted.pdf", _generate_encrypted()))

    print("\nDone. %d files in %s" % (len(written), PDF_DIR))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())